<?php require_once "db.php"; $posts=$conn->query("SELECT * FROM blog_posts WHERE status='published' ORDER BY id DESC"); require_once "includes/header.php"; ?>
<main class="content-page"><section class="page-hero"><div><span>THE KHUSHBU JOURNAL</span><h1>Stories & Insights</h1><p>Jewellery inspiration, styling ideas and stories from our world.</p></div></section><section class="section"><div class="container"><div class="blog-grid"><?php if($posts&&$posts->num_rows):while($post=$posts->fetch_assoc()):?><article class="blog-card"><?php if($post["image"]):?><img src="uploads/blog/<?=htmlspecialchars($post["image"])?>" alt="<?=htmlspecialchars($post["title"])?>"><?php endif;?><div class="blog-card-body"><span><?=date("d M Y",strtotime($post["created_at"]))?></span><h2><?=htmlspecialchars($post["title"])?></h2><p><?=htmlspecialchars($post["excerpt"] ?: substr(strip_tags($post["content"]),0,180)."…")?></p></div></article><?php endwhile;else:?><div class="empty-state"><h2>Our journal is coming soon</h2><p>Beautiful stories and jewellery guides will be published here.</p></div><?php endif;?></div></div></section></main><?php require_once "includes/footer.php"; ?>